382	interface SeriesRec {
383	  id: string;
384	}
385	
386	interface WaitlistRec {
387	  id: string; // 候补标识 W0001…，稳定且不复用
388	  kind: WaitlistKind; // fixed=固定时段；flexible=弹性时段（窗口内寻找最早连续时长）
389	  resourceIds: string[]; // 原请求资源（按标识排序）
390	  start: string; // 原请求开始时间；弹性项为窗口开始
391	  end: string; // 原请求结束时间；弹性项为窗口结束
392	  durationMinutes?: number; // 仅弹性项：所需连续时长（正整数分钟，不超过窗口长度）
393	  status: WaitlistStatus;
394	  seq: number; // 登记序号：1 基，列表与处理均按此稳定排序，重启后仍在
395	  bookingId?: string; // 已兑现时关联的普通预约标识
396	}
