407	interface BatchOpItem {
408	  bookingId: string;
409	  seriesId?: string; // 提交时的系列归属（无系列则不含）
410	  before: {start: string; end: string; resourceIds: string[]}; // 改期前安排
411	  after: {start: string; end: string; resourceIds: string[]}; // 改期后安排（提交目标）
412	}
413	
414	interface BatchOpRec {
415	  id: string; // 批量改期操作标识 O0001…，稳定且不复用（即使记录已撤销）
416	  status: BatchOpStatus;
417	  items: BatchOpItem[]; // 按提交（清单）顺序
418	}
419	
420	// 一次 iCalendar 导入建立的“UID -> 预约/系列”永久关联：
421	// 独立事件（无 RRULE）：bookingId 指向首次导入生成的普通预约，count/exdates 缺省。
422	// 按周重复事件（RRULE:FREQ=WEEKLY;COUNT=n）：seriesId 指向首次导入创建的系列，
423	// occurrences 按原发生顺序记录每个未排除发生的原开始时间（YYYY-MM-DDTHH:mm）与
424	// 对应成员预约标识（排除的发生不在其中）；count/exdates 为首次请求的重复参数。
425	// exceptions 按原发生时间关联该次发生的改期例外（RECURRENCE-ID = 原开始，
426	// start/end 为例外的改期后起止；首次请求无例外时为空数组），同一次发生至多一个
427	// 例外，被替换原时段以例外时间参与覆盖与冲突校验。
428	// 快照保留首次导入的时间与资源集合（之后成员被改期/取消、系列被整体取消也不变），
429	// 重放按快照比对本次请求，身份不依赖导入文件路径
