431	  uid: string; // 解码后的 UID（区分大小写），同一数据文件内唯一
432	  bookingId?: string; // 独立事件：首次导入生成的预约标识
433	  seriesId?: string; // 重复事件：首次导入创建的系列标识
434	  start: string; // 首次导入的开始时间快照（首项 DTSTART）YYYY-MM-DDTHH:mm
435	  end: string; // 首次导入的结束时间快照（首项 DTEND）
436	  resourceIds: string[]; // 首次导入的资源集合快照（按标识排序）
437	  count?: number; // 仅重复事件：RRULE COUNT（1..100000，含首项）
438	  exdates?: string[]; // 仅重复事件：排除集合快照（原开始时间文本，按时间排序去重）
439	  occurrences?: Array<{start: string; bookingId: string}>; // 仅重复事件：原发生时间 -> 成员
440	  exceptions?: Array<{recurrenceId: string; start: string; end: string}>; // 仅重复事件：按原发生关联的例外起止（按原发生顺序）
441	}
