  if (r.type !== 'venue' && r.type !== 'equipment' && r.type !== 'person') {
    bad(`${at}(${r.id}).type 非法: ${String(r.type)}`);
  }
  if (typeof r.name !== 'string' || r.name.trim() === '') bad(`${at}(${r.id}).name 不能为空`);
