3236	// 候选资源组合的最早可行时段查询（find-slot，只读）
3237	//
3238	// 给定营业地时间窗口、所需连续分钟数与有顺序的需求组（每组列出可任选其一的
3239	// 已登记资源），在窗口内寻找能同时满足全部需求的最早开始分钟：每组恰选一个
3240	// 候选，全部所选资源互不相同，并在整个时段保持同一组合（不中途更换资源、
3241	// 不拼接间断时间）。各资源空闲时间 = 开放区间合并重叠或相接后扣除有效停用
3242	// 并集与当前有效预约占用（取消的预约/停用与未兑现候补不阻挡），区间左闭
3243	// 右开、端点相接可行。同一最早开始有多个组合时，按组顺序的资源标识序列取
3244	// 字典序最小者。本命令只读一份完整快照：不取写入保护、不创建任何记录、
3245	// 不写数据文件或推进计数；方案不保留位置，后续创建预约仍检查最新状态。
3246	// ---------------------------------------------------------------------------
3247	
3248	interface RequirementGroup {
3249	  index: number; // 1 基，需求组顺序
3250	  candidates: string[]; // 已校验、按标识排序的候选资源（组内输入顺序不影响结果）
3251	}
3252	
3253	// 解析并校验需求组：至少一组（由调用方保证），每组非空；
3254	// 组内重复或未知资源拒绝；同一资源允许出现在不同组（求解时保证所选互不相同）
3255	function parseRequirementGroups(store: Store, rawGroups: string[]): RequirementGroup[] {
3256	  return rawGroups.map((raw, i) => {
3257	    const label = `第 ${i + 1} 需求组`;
3258	    const ids = raw.split(',').map((s) => s.trim());
3259	    if (ids.some((s) => s === '')) {
3260	      throw new BizError(
3261	        `${label}为空或含空项: “${raw}”，应为逗号分隔的已登记资源标识（如 R0001,R0002）`,
3262	      );
3263	    }
3264	    const seen = new Set<string>();
3265	    const dupes: string[] = [];
3266	    for (const id of ids) {
3267	      if (seen.has(id) && !dupes.includes(id)) dupes.push(id);
3268	      seen.add(id);
3269	    }
3270	    if (dupes.length > 0) throw new BizError(`${label}内候选资源重复: ${dupes.join('、')}`);
3271	    const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
3272	    if (unknown.length > 0) throw new BizError(`${label}含未知资源标识: ${unknown.join('、')}`);
3273	    return {index: i + 1, candidates: [...seen].sort()};
3274	  });
3275	}
3276	
3277	// 已放置活动 [s, e) 在资源 r 上对“其他活动”的活动域阻挡区间：
3278	// 两活动共用 r 时，前者结束后须留 r.teardownMinutes、后者开始前须留
3279	// r.prepMinutes（前后两种相邻顺序合计相同），故活动域中阻挡区间为
3280	// [s - 准备 - 整理, e + 准备 + 整理)。从候选活动空闲段中扣除它即精确实现
3281	// “共同资源上实际占用重叠才冲突、扩张后端点相接可行”。
3282	function activityBlockOn(r: ResourceRec, s: number, e: number): [number, number] {
3283	  const gap = r.prepMinutes + r.teardownMinutes;
3284	  return [s - gap, e + gap];
3285	}
3286	
3287	// 固定开始分钟上的字典序最小可行资源序列：逐组按标识升序试探，
3288	// 选定前先用增广路匹配确认剩余组仍能各选一个互不相同的可用候选，
3289	// 因此不会因前组贪选较小标识而漏掉需要调整前组选择的可行组合，
3290	// 也不会把每组各自可行误当成整体可行
3291	function lexMinAssignment(
3292	  groups: RequirementGroup[],
3293	  usable: (id: string) => boolean,
3294	): string[] | null {
3295	  const chosen: string[] = [];
3296	  const used = new Set<string>();
3297	
3298	  // 第 from 组起（0 基）在 used 之外能否各选一个互不相同的可用候选
3299	  const restMatchable = (from: number): boolean => {
3300	    const match = new Map<string, number>(); // 资源 -> 组下标
3301	    const tryAssign = (g: number, seen: Set<string>): boolean => {
3302	      for (const id of groups[g].candidates) {
3303	        if (used.has(id) || seen.has(id) || !usable(id)) continue;
3304	        seen.add(id);
3305	        const owner = match.get(id);
3306	        if (owner === undefined || tryAssign(owner, seen)) {
3307	          match.set(id, g);
3308	          return true;
3309	        }
3310	      }
3311	      return false;
3312	    };
3313	    for (let g = from; g < groups.length; g++) {
3314	      if (!tryAssign(g, new Set())) return false;
3315	    }
3316	    return true;
3317	  };
3318	
3319	  for (let g = 0; g < groups.length; g++) {
3320	    let picked: string | null = null;
3321	    for (const id of groups[g].candidates) {
3322	      if (used.has(id) || !usable(id)) continue;
3323	      used.add(id);
3324	      if (restMatchable(g + 1)) {
3325	        picked = id;
3326	        break;
3327	      }
3328	      used.delete(id);
3329	    }
3330	    if (picked === null) return null;
3331	    chosen.push(picked);
3332	  }
3333	  return chosen;
3334	}
3335	
3336	// 窗口内能同时满足全部需求的最早活动开始分钟及该时刻字典序最小的组合；
3337	// 每个候选资源的空闲为“活动域”区间（占用域扣除停用/预约实际占用后，再向内
3338	// 收缩该资源的准备/整理分钟），故活动 [s, s+duration) 落在此区间即保证
3339	// [s-准备, s+duration+整理) 全程实际可用；准备/整理可伸出窗口。
3340	// 最早可行开始必为某候选资源某段活动空闲的起点，逐一升序试探即可。
3341	function findEarliestSlot(
3342	  store: Store,
3343	  groups: RequirementGroup[],
3344	  wStart: number,
3345	  wEnd: number,
3346	  duration: number,
3347	): {startMin: number; endMin: number; picks: string[]} | null {
3348	  const freeById = new Map<string, Array<[number, number]>>();
3349	  const starts = new Set<number>();
3350	  for (const g of groups) {
3351	    for (const id of g.candidates) {
3352	      if (freeById.has(id)) continue;
3353	      const free = resourceActivityFreeSegments(store, id, wStart, wEnd);
3354	      freeById.set(id, free);
3355	      for (const [s, e] of free) {
3356	        if (e - s >= duration) starts.add(s);
3357	      }
3358	    }
3359	  }
