// 弹性组合候补的候选需求组 groups（缺省为旧式弹性候补：resourceIds 即
// “全部资源须同时可用”的单一需求，旧文件无需迁移）。
// 结构、引用与 resourceIds 并集任一非法即视为数据损坏，拒绝加载。
let groups: string[][] | undefined;
if (w.groups !== undefined) {
  if (kind !== 'flexible') {
    bad(`${at}(${w.id}) 固定时段候补不应携带 groups 候选需求组`);
  }
  if (!Array.isArray(w.groups) || w.groups.length === 0) {
    bad(`${at}(${w.id}).groups 必须是至少含一个非空需求组的数组`);
  } else {
    groups = [];
    const groupUnion = new Set<string>();
    let groupsValid = true;
    w.groups.forEach((g, gi) => {
      const gat = `${at}(${w.id}).groups[${gi}]`;
      if (!Array.isArray(g) || g.length === 0) {
        bad(`${gat} 必须是非空数组（第 ${gi + 1} 个需求组的候选资源标识）`);
        groupsValid = false;
        return;
      }
      const gseen = new Set<string>();
      for (const rid of g) {
        if (typeof rid !== 'string') {
          bad(`${gat} 含非字符串候选: ${String(rid)}`);
          groupsValid = false;
          continue;
        }
        if (gseen.has(rid)) {
          bad(`${gat} 第 ${gi + 1} 个需求组内候选资源重复: ${rid}`);
          groupsValid = false;
        }
        gseen.add(rid);
        if (!resourceIds.has(rid)) {
          bad(`${gat}(${w.id}) 引用了未知资源: ${rid}`);
          groupsValid = false;
        }
        groupUnion.add(rid);
      }
      // 持久化的每组候选按标识排序；与排序结果不一致同样判为损坏
      const sorted = [...gseen].sort();
      if (g.length !== sorted.length || g.some((rid, k) => rid !== sorted[k])) {
        bad(`${gat} 候选资源未按标识排序（候选书写顺序不应落盘）`);
        groupsValid = false;
      }
      groups!.push(sorted);
    });
    // resourceIds 必须恰好是全部需求组候选的去重并集（资源可跨组出现）
    if (groupsValid) {
      const declared = new Set(w.resourceIds as unknown[] as string[]);
      const sameSet =
        declared.size === groupUnion.size && [...groupUnion].every((rid) => declared.has(rid));
      if (!sameSet) {
        bad(
          `${at}(${w.id}).groups 的候选并集与 resourceIds 不一致（resourceIds 须为全部需求组候选的去重并集）`,
        );
      }
    }
  }
}

