  const proc = ok(df, ['process-waitlist'], '缓冲跨窗处理');
  // 10:30-11:30，整理伸至 12:00 恰为开放端点（相接，可行）
  assertFulfillment(proc.stdout, 'W0001', 'B0002', '2026-10-12T10:30', '2026-10-12T11:30', ['R0001', 'R0002'], '缓冲跨窗 10:30');

  // 若再占 R0001 至 11:00（实际占用至 11:30），活动 11:00 时整理到 12:00 边界——
  // 这里改为登记一条新候补并令 R0001 仅剩不可用段，验证受阻诊断不空指针
  addFlexGroup(df, ['R0001', 'R0002'], '2026-10-12T11:00/2026-10-12T12:00', '60', '登记必受阻候补');
