test('缓冲跨窗：整理伸出窗口须实际可用；停用端点相接可行', (t) => {
  const dir = tempDir(t);
  const df = join(dir, 'data.json');
  // R0001 开放到 12:00，整理 30 分钟；R0002 全天开放
  addResource(df, '半日房', [['2026-10-12T08:00', '2026-10-12T12:00']], {teardown: '30'}); // R0001
  addResource(df, '全日房'); // R0002

  // 窗口 08:00-12:00，dur 60：活动最晚开始 11:00（结束 12:00，整理伸至 12:30）
  // R0001 12:00 即不开放 -> 12:30 整理无实际可用，故 11:00 不可行，最晚开始 10:30
  // 停用 R0001 12:00-12:30（恰在开放之外，不起额外作用）；真正约束是开放边界
  // 先占 R0001 08:00-10:30（实际占用 08:00-11:00）：组合 [R0001],[R0002] 最早只能 10:30
  ok(
    df,
    ['create-booking', '--resource', 'R0001', '--start', '2026-10-12T08:00', '--end', '2026-10-12T10:30'],
    '占 R0001 至整理后 11:00',
  );
  addFlexGroup(df, ['R0001', 'R0002'], '2026-10-12T08:00/2026-10-12T12:00', '60', '登记组合候补');
  const proc = ok(df, ['process-waitlist'], '缓冲跨窗处理');
  // 10:30-11:30，整理伸至 12:00 恰为开放端点（相接，可行）
  assertFulfillment(proc.stdout, 'W0001', 'B0002', '2026-10-12T10:30', '2026-10-12T11:30', ['R0001', 'R0002'], '缓冲跨窗 10:30');

  // 若再占 R0001 至 11:00（实际占用至 11:30），活动 11:00 时整理到 12:00 边界——
  // 这里改为登记一条新候补并令 R0001 仅剩不可用段，验证受阻诊断不空指针
  addFlexGroup(df, ['R0001', 'R0002'], '2026-10-12T11:00/2026-10-12T12:00', '60', '登记必受阻候补');
  // 窗口 11:00-12:00、dur 60：唯一活动 11:00-12:00，R0001 整理至 12:30 超出开放 -> 无完整组合
  const proc2 = ok(df, ['process-waitlist'], '短窗缓冲受阻');
  assert.match(proc2.stdout, /继续等待 W0002/);
  assert.match(proc2.stdout, /窗口内无完整可行组合/);
});

